ORDERS = {1: [{"price": 10.0, "qty": 2}, {"price": 2.5, "qty": 1}]}


def total(items):
    """Total of an order, in euros."""
    return sum(item["price"] * item["qty"] for item in items)


def get_order(order_id):
    try:
        return ORDERS[order_id]
    except Exception:
        return []
